local card={api_version=1,id="EX1_154",name="Wrath",text="<b>Choose One -</b>\nDeal $3 damage to a minion; or $1 damage\nand draw a card.",set="EXPERT1",type="spell",class="druid",rarity="common",spell_school="nature",cost=2,keywords={"choose_one"},target_mode="required",targets=function(ctx)return ctx:minions()end}
function card.on_choose_one(ctx,self,target)ctx:set_data(self,"wrath_target",target);ctx:choose_options(ctx:controller(self),"Choose One",{{card_id="EX1_154a",label="Deal 3 damage"},{card_id="EX1_154b",label="Deal 1 damage and draw"}},"chosen")end
function card.chosen(ctx,self,c)local t=ctx:get_data(self,"wrath_target");cardlib.effects.damage(ctx, t,c=="EX1_154a" and 3 or 1);if c=="EX1_154b" then ctx:draw(ctx:controller(self),1)end end
function card.on_choose_multiple(ctx,self,target)cardlib.effects.damage(ctx, target,4);ctx:draw(ctx:controller(self),1)end
card.tokens={{id="EX1_154a", spell_school = "nature",name="Solar Wrath",text="Deal $3 damage to a minion.",set="EXPERT1",type="spell",class="druid",collectible=false,cost=2},{id="EX1_154b", spell_school = "nature",name="Nature's Wrath",text="Deal $1 damage to a minion. Draw a card.",set="EXPERT1",type="spell",class="druid",collectible=false,cost=2}}
return card
